async ({ workspace: { search, edit }, delivery: { format, listChangedFiles, openPullRequest } }) => {
  const m = (await search("## [Unreleased]", { path: "CHANGELOG.md" })).matches[0]!;
  await edit(m.file, { revision: m.revision, changes: [{ kind: "insertAfter", anchor: m.anchor, content: "\n### Changed\n\n- **Breaking:** Pit supports Pi 1.5.2, the version `package-lock.json` now pins, including `@earendil-works/pi-codemode` 1.5.2, which Pit installs as its own copy. Update Pi to 1.5.2 with this release.\n- The runtime dependency audit in CI and the Release workflow skips the withdrawn picomatch advisory GHSA-fc5q-39xc-vjpf (#411)." }] });
  await format();
  const files = (await listChangedFiles({ includeDeleted: true })).files;
  return (await openPullRequest({
    branch: "deps/combined-1.5.2",
    files,
    message: "build(deps): update Pi packages to 1.5.2, oxfmt 0.78.0, and oxlint 1.93.0\n\nCombines Dependabot PRs #404, #405, #406, #407, and #408. Pit pins the Pi\npackages to the versions pi-coding-agent requires, so pi-ai and\npi-codemode 1.5.2 need pi-coding-agent and pi-tui 1.5.2 as well.",
    title: "Update Pi packages to 1.5.2, oxfmt 0.78.0, oxlint 1.93.0",
    body: "Combines Dependabot #404, #405, #406, #407, and #408 into one lockfile update.\n\n`npm run package:check` requires Pit's shared Pi packages to match what the pinned `pi-coding-agent` requires, so #406 (pi-ai 1.5.2) and #408 (pi-codemode 1.5.2) cannot pass on their own: this also bumps `pi-coding-agent` and `pi-tui` (dev and peer) to 1.5.2 and updates the README's supported Pi version and the changelog.\n\nLocal `delivery.validate()` passed: check, tests, coverage, package check.",
  })) as unknown as PitJsonValue;
}
